# Powertools Metrics for Lambda (TypeScript/JavaScript)

Record count metrics with the actual Powertools Metrics implementation and flush them as CloudWatch Embedded Metric Format (EMF) JSON. CloudWatch extracts EMF asynchronously from the Lambda log stream; this helper does not call `PutMetricData`.

## Install and use

Install `@aws-lambda-powertools/metrics` at exactly 2.36.0 and run in Node.js 20 or newer in Lambda.

```js
import { createMetrics, recordCount, flushMetrics } from './src/metrics.mjs';
const metrics = createMetrics({ namespace: 'Payments', service_name: 'capture' });
export const handler = async (event) => {
  try {
    recordCount(metrics, 'PaymentAccepted');
    return { statusCode: 200 };
  } finally {
    flushMetrics(metrics);
  }
};
```

Use low-cardinality dimensions such as environment or service. Do not put customer IDs, request IDs, or other high-cardinality values in dimensions; use metadata when appropriate. Powertools enforces EMF metric and dimension limits. `publishStoredMetrics()` writes to stdout; it is not proof CloudWatch has ingested the document.

## Native private preview and boundary

`preview.mjs` runs the actual Powertools Metrics API in Node.js, captures and parses its local EMF JSON output, and returns only bounded counts. It does not publish to CloudWatch; a local log line does not prove CloudWatch ingestion. Hosted preview remains unavailable because the Worker Loader uses a compatibility date before the `node:console` module supported by this library.

## Files and source

Original integration code is Apache-2.0. Powertools Metrics 2.36.0 is MIT-0; its pinned repository revision and published tarball integrity are recorded in `source-provenance.json`.

{
  "name": "@secondwind/lambda-powertools-metrics-ts",
  "version": "1.0.0",
  "private": true,
  "type": "module",
  "engines": {
    "node": ">=20"
  },
  "description": "A Node.js Lambda helper that records bounded count metrics and flushes the actual Powertools Metrics EMF document to standard output.",
  "license": "Apache-2.0",
  "dependencies": {
    "@aws-lambda-powertools/metrics": "2.36.0"
  }
}

import { createMetrics, recordCount, flushMetrics } from './src/metrics.mjs';

const SLUG = 'lambda-powertools-metrics-ts';

/** Native Node preview: exercise Powertools Metrics and parse its local EMF output. */
export async function preview({ configuration, selected_components } = {}) {
  if (!configuration || configuration.language !== 'javascript'
      || typeof configuration.namespace !== 'string' || typeof configuration.service_name !== 'string'
      || !Array.isArray(selected_components) || selected_components.length !== 1
      || selected_components[0] !== 'base') {
    return { ok: false, status: 'invalid', slug: SLUG, operation_count: 0, diagnostic_codes: ['configuration_invalid'] };
  }
  const captured = [];
  const originals = Object.fromEntries(['log', 'info', 'warn', 'error'].map(key => [key, console[key]]));
  const originalWrite = process.stdout.write;
  try {
    for (const key of Object.keys(originals)) console[key] = (...args) => { captured.push(args.map(String).join(' ')); };
    process.stdout.write = (chunk, encoding, callback) => { captured.push(String(chunk)); if (typeof encoding === 'function') encoding(); else if (callback) callback(); return true; };
    const metrics = createMetrics(configuration);
    recordCount(metrics, 'ProtectedPreviewCount', 1);
    flushMetrics(metrics);
    const emf = captured.map(line => { try { return JSON.parse(line); } catch { return null; } }).find(row => row?._aws?.CloudWatchMetrics);
    if (!emf || emf.ProtectedPreviewCount !== 1) throw new Error('emf_output_missing');
    return { ok: true, status: 'valid', slug: SLUG, operation_count: 1, diagnostic_codes: ['local_emf_output_only'], selected_components };
  } catch {
    return { ok: false, status: 'unavailable', slug: SLUG, operation_count: 0, diagnostic_codes: ['runtime_unavailable'] };
  } finally {
    process.stdout.write = originalWrite;
    for (const [key, original] of Object.entries(originals)) console[key] = original;
  }
}

import { Metrics, MetricUnit } from '@aws-lambda-powertools/metrics';

const SERVICE = /^[A-Za-z0-9_.-]{1,64}$/;
const METRIC = /^[A-Za-z][A-Za-z0-9_.-]{0,254}$/;

export function createMetrics({ namespace, service_name, default_dimensions = {} } = {}) {
  if (typeof namespace !== 'string' || !namespace.trim() || namespace.length > 255) throw new Error('invalid_namespace');
  if (typeof service_name !== 'string' || !SERVICE.test(service_name)) throw new Error('invalid_service_name');
  if (!default_dimensions || Array.isArray(default_dimensions) || typeof default_dimensions !== 'object'
      || Object.keys(default_dimensions).length > 8
      || Object.values(default_dimensions).some(value => typeof value !== 'string' || value.length > 250)) {
    throw new Error('invalid_default_dimensions');
  }
  return new Metrics({ namespace, serviceName: service_name, defaultDimensions: default_dimensions });
}

export function recordCount(metrics, name, value = 1) {
  if (!metrics || typeof metrics.addMetric !== 'function') throw new Error('metrics_instance_required');
  if (typeof name !== 'string' || !METRIC.test(name)) throw new Error('invalid_metric_name');
  if (typeof value !== 'number' || !Number.isFinite(value) || value < 0) throw new Error('invalid_metric_value');
  metrics.addMetric(name, MetricUnit.Count, value);
}

/** Emits an EMF JSON document to stdout; CloudWatch ingestion is asynchronous. */
export function flushMetrics(metrics) {
  if (!metrics || typeof metrics.publishStoredMetrics !== 'function') throw new Error('metrics_instance_required');
  metrics.publishStoredMetrics();
}
